import type { AppError } from '../kernel/errors.js';
import { lookupOrder, markOrderAsRefunded } from './order.service.js';

export interface RefundResult {
  readonly success: boolean;
  readonly error?: AppError;
}

export function refundOrder(orderId: string): RefundResult {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return {
      success: false,
      error: {
        code: 'NOT_FOUND',
        message: `Order ${orderId} not found`,
      },
    };
  }

  if (order.refunded) {
    return {
      success: false,
      error: {
        code: 'ALREADY_REFUNDED',
        message: `Order ${orderId} has already been refunded`,
      },
    };
  }

  if (order.total < 10) {
    return {
      success: false,
      error: {
        code: 'INSUFFICIENT_AMOUNT',
        message: `Order ${orderId} total of ${order.total} is below the minimum refundable amount of 10`,
      },
    };
  }

  markOrderAsRefunded(orderId);
  return { success: true };
}

